      status: 'RUNNING',
      input: input.payload,
      version: 1,
      createdAt: new Date(),
      updatedAt: new Date(),
    };
    this.executions.set(this.key(input.organizationId, execution.id), execution);
    await this.persistExecution(execution);
    return this.run(execution, workflow, input.signal);
  }

